# Minimal Config.pm stub for bootstrapping Perl on Plan9/APExp.
# The real Config.pm is generated by ./Configure and contains hundreds
# of build-system values.  This stub provides enough for ExtUtils::Miniperl's
# writemain() to run (it only needs lib_ext, static_ext, path_sep, usedl).
# Expand as needed when more of the Perl build system is wired up.
package Config;

our %Config = (
    # Library / linking
    lib_ext      => '.a',
    dlext        => 'so',
    static_ext   => '',   # no static XS extensions
    usedl        => '',   # no dynamic loading on Plan9
    libperl      => 'libperl.a',
    perllibs     => '',
    ldflags      => '',
    ccflags      => '',
    ccdlflags    => '',
    archlibexp   => '/sys/lib/perl',

    # Paths
    path_sep     => ':',

    # Identity
    osname       => 'plan9',
    archname     => 'amd64-plan9',
    version      => '5.042002',
    patchlevel   => '42',
    subversion   => '2',
    perl_version => '5042002',
);

sub import {
    # Export %Config into the caller's namespace the same way the real
    # Config.pm does — by aliasing the glob.
    my $caller = caller;
    no strict 'refs';
    *{"${caller}::Config"} = \%Config;
}

1;
